-- Let's check how many distinct sitetie values have electrical_performance data
SELECT COUNT(DISTINCT pr.sitetie) FROM plant_record pr 
JOIN electrical_performance ep ON ep.snaplink = pr.snapkey;

-- Get all unique keys across all jsonb sections
SELECT DISTINCT key FROM electrical_performance, 
  jsonb_each(elec_perf_snapshot) WHERE true LIMIT 50;

-- Get all nested keys
SELECT DISTINCT jsonb_object_keys(elec_perf_snapshot->'power') as power_key FROM electrical_performance;
SELECT DISTINCT jsonb_object_keys(elec_perf_snapshot->'efficiency') as eff_key FROM electrical_performance;
